import re

def entities(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)

    objects_node = None
    for child in children_nodes:
        if child.get("title", "").endswith(": Objects"):
            objects_node = child
            break

    if objects_node is None:
        return []

    result = []
    for line_idx, line in enumerate(objects_node.get("lines", [])):
        # e.g. "Object 0: gray rubber sphere (color=gray, material=rubber, shape=sphere)"
        m = re.match(r'Object (\d+): (.+?) \(', line)
        if m:
            obj_id = m.group(1)
            description = m.group(2)
            result.append({"id": obj_id, "description": description})

    return result


def recorded_end(doc, scope) -> float or None:
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)

    motion_node = None
    for child in children_nodes:
        if child.get("title", "").endswith(": Motion log"):
            motion_node = child
            break

    if motion_node is None:
        return None

    max_frame = -1
    for row_idx, row in table_rows(motion_node):
        try:
            f = int(row["frame"])
            if f > max_frame:
                max_frame = f
        except (ValueError, KeyError):
            pass

    return float(max_frame) if max_frame >= 0 else None


def _find_node(scope_node, suffix):
    for child in children(doc_global, scope_node):
        if child.get("title", "").endswith(suffix):
            return child
    return None


# We need a way to reference children without capturing doc
# Re-implement helpers inline since doc is passed as parameter

def inputs(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    scope_children = children(doc, scope_node)

    events_node = None
    motion_node = None

    for child in scope_children:
        t = child.get("title", "")
        if t.endswith(": Events"):
            events_node = child
        elif t.endswith(": Motion log"):
            motion_node = child

    if events_node is None:
        return []

    # Build lookup: (frame, obj_id) -> (row_index, row_dict)
    motion_lookup = {}
    if motion_node:
        for row_idx, row in table_rows(motion_node):
            frame = int(row["frame"])
            om = re.match(r'(\d+)\s', row.get("object", ""))
            if om:
                obj_id = om.group(1)
                motion_lookup[(frame, obj_id)] = (row_idx, row)

    inputs_list = []

    for line_idx, line in enumerate(events_node.get("lines", [])):
        fm = re.match(r'Frame (\d+): (.+)', line)
        if not fm:
            continue

        frame = int(fm.group(1))
        rest = fm.group(2)

        # Object is in view when the video begins
        if "is in view when the video begins" in rest:
            om = re.match(r'Object (\d+)\s*\(.+?\)\s*is in view', rest)
            if om:
                obj_id = om.group(1)
                locs = [[events_node["node_id"], line_idx]]
                fields = {}

                ridx, rrow = motion_lookup.get((frame, obj_id), (None, {}))
                if rrow:
                    for col in ["x", "y", "vx", "vy", "speed"]:
                        try:
                            fields[col] = float(rrow[col])
                        except (KeyError, ValueError):
                            pass
                    locs.append([motion_node["node_id"], ridx, ["frame", "object", "x", "y", "vx", "vy", "speed"]])

                inputs_list.append({
                    "id": f"init_{obj_id}",
                    "time": float(frame),
                    "kind": "initial_presence",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": locs
                })

        # Object enters the scene
        elif "enters the scene" in rest:
            om = re.match(r'Object (\d+)\s*\(.+?\)\s*enters the scene', rest)
            if om:
                obj_id = om.group(1)
                locs = [[events_node["node_id"], line_idx]]
                fields = {}

                ridx, rrow = motion_lookup.get((frame, obj_id), (None, {}))
                if rrow:
                    for col in ["x", "y", "vx", "vy", "speed"]:
                        try:
                            fields[col] = float(rrow[col])
                        except (KeyError, ValueError):
                            pass
                    locs.append([motion_node["node_id"], ridx, ["frame", "object", "x", "y", "vx", "vy", "speed"]])

                inputs_list.append({
                    "id": f"entry_{obj_id}_{frame}",
                    "time": float(frame),
                    "kind": "entry",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": locs
                })

    return inputs_list


def outcomes(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    scope_children = children(doc, scope_node)

    events_node = None

    for child in scope_children:
        if child.get("title", "").endswith(": Events"):
            events_node = child
            break

    if events_node is None:
        return []

    outcomes_list = []

    for line_idx, line in enumerate(events_node.get("lines", [])):
        fm = re.match(r'Frame (\d+): (.+)', line)
        if not fm:
            continue

        frame = int(fm.group(1))
        rest = fm.group(2)

        # Collision
        cm = re.match(r'Object (\d+)\s*\(.+?\)\s*and\s*Object (\d+)\s*\(.+?\)\s*collide', rest)
        if cm:
            outcomes_list.append({
                "time": float(frame),
                "kind": "collision",
                "entities": [cm.group(1), cm.group(2)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
            continue

        # Exit
        em = re.match(r'Object (\d+)\s*\(.+?\)\s*exits the scene', rest)
        if em:
            outcomes_list.append({
                "time": float(frame),
                "kind": "exit",
                "entities": [em.group(1)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })

    return outcomes_list


def params(doc, scope) -> dict:
    return {"stationary_threshold": 0.1}


# ---- step 2: forward model ----
import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    end_time = recorded_end(doc, scope)
    if horizon is None:
        horizon = end_time if end_time is not None else 128.0
    if start is None:
        start = 0.0
    if start is None and horizon is None:
        start = 0.0
        horizon = 128.0

    # Parse materials from entity descriptions
    ent_list = entities(doc, scope)
    materials = {e["id"]: e["description"].split()[1] for e in ent_list}

    state = {}
    outcomes = []
    sorted_inputs = sorted(inputs, key=lambda x: x["time"])

    # Run from frame 0 to horizon to correctly rebuild state at `start`
    t = 0
    while t <= int(horizon):
        # Apply inputs scheduled for this frame
        for inp in sorted_inputs:
            if inp["time"] == t:
                eid = inp["entities"][0]
                state[eid] = {
                    "x": inp["fields"]["x"], "y": inp["fields"]["y"],
                    "vx": inp["fields"]["vx"], "vy": inp["fields"]["vy"],
                    "mat": materials.get(eid, "rubber")
                }

        # Collision detection & resolution
        objs = list(state.keys())
        for i in range(len(objs)):
            for j in range(i+1, len(objs)):
                o1, o2 = objs[i], objs[j]
                s1, s2 = state[o1], state[o2]
                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist_sq = dx*dx + dy*dy

                # Collision threshold estimated from CLEVRER object radii
                if dist_sq < 0.48**2 and dist_sq > 1e-6:
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dot = dvx*dx + dvy*dy

                    # Only resolve if approaching
                    if dot > 0:
                        # Elastic impulse exchange (equal mass assumption)
                        impulse = dot / dist_sq
                        s1["vx"] -= impulse * dx
                        s1["vy"] -= impulse * dy
                        s2["vx"] += impulse * dx
                        s2["vy"] += impulse * dy

                        if t >= start:
                            outcomes.append({
                                "time": float(t),
                                "kind": "collision",
                                "entities": [o1, o2],
                                "value": None,
                                "src": []
                            })

        # Update positions, apply friction, check exits
        for eid, s in list(state.items()):
            speed = math.hypot(s["vx"], s["vy"])
            # Friction coefficients estimated from motion logs
            friction = 0.01 if s["mat"] == "rubber" else 0.017
            if speed > 0:
                factor = max(0.0, speed - friction) / speed
                s["vx"] *= factor
                s["vy"] *= factor

            s["x"] += s["vx"]
            s["y"] += s["vy"]

            # Exit detection when leaving camera bounds
            if abs(s["x"]) > 4.2 or abs(s["y"]) > 4.2:
                if t >= start:
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": []
                    })
                del state[eid]

        t += 1

    return outcomes

