def run_explore():
    scopes = ["Video 10935", "Video 11091", "Video 11110", "Video 11368", "Video 11394", "Video 14967"]

    decays = {"rubber": [], "metal": []}
    exits = []

    for scope in scopes:
        sn = node_by_title(doc, scope)
        if not sn: continue
        ch = children(doc, sn)
        motion_node = events_node = objects_node = None
        for c in ch:
            t = c.get("title", "")
            if t.endswith(": Motion log"): motion_node = c
            elif t.endswith(": Events"): events_node = c
            elif t.endswith(": Objects"): objects_node = c

        if not motion_node or not events_node: continue

        mats = {}
        if objects_node:
            for line in objects_node.get("lines", []):
                m = re.match(r'Object (\d+): \w+ (\w+) \w+', line)
                if m: mats[m.group(1)] = m.group(2)

        m_data = {}
        for row in motion_node["table"]["rows"]:
            f = int(row[0])
            om = re.match(r'(\d+)\s', row[1])
            if om:
                oid = om.group(1)
                m_data[(oid, f)] = {"vx": float(row[4]), "vy": float(row[5]), "speed": float(row[6])}

        coll_objs = set()
        for line in events_node.get("lines", []):
            cm = re.match(r'Frame (\d+): Object (\d+)\s*\(.*?\)\s*and\s*Object (\d+)\s*\(.*?\)\s*collide', line)
            if cm:
                coll_objs.add((cm.group(2), int(cm.group(1))))
                coll_objs.add((cm.group(3), int(cm.group(1))))

        em = re.compile(r'Frame (\d+): Object (\d+)\s*\(.*?\)\s*exits the scene')
        for line in events_node.get("lines", []):
            m = em.match(line)
            if m:
                ef, eo = int(m.group(1)), m.group(2)
                if (eo, ef) in m_data:
                    d = m_data[(eo, ef)]
                    exits.append((scope, ef, eo, mats.get(eo, "?"), d["vx"], d["vy"]))

        all_ids = set(oid for (oid, f) in m_data.keys())
        for oid in all_ids:
            frames = sorted([f for (o, f) in m_data.keys() if o == oid])
            mat = mats.get(oid, "?")
            for i in range(len(frames)-1):
                f1, f2 = frames[i], frames[i+1]
                if f2 - f1 != 8: continue
                if (oid, f1) in coll_objs or (oid, f2) in coll_objs: continue
                s1 = m_data[(oid, f1)]["speed"]
                s2 = m_data[(oid, f2)]["speed"]
                if s1 > 0.5:
                    decay_per_frame = (s1 - s2) / 8.0
                    if mat in decays:
                        decays[mat].append(decay_per_frame)

    print("Friction (decay/frame):")
    for mat, vals in decays.items():
        if vals:
            avg = sum(vals)/len(vals)
            print(f"  {mat}: avg={avg:.4f}, samples={len(vals)}")

    print("\nExits (scope, frame, obj, mat, vx, vy):")
    for ex in exits:
        print(f"  {ex}")

