import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    end_time = recorded_end(doc, scope)
    if horizon is None:
        horizon = end_time if end_time is not None else 127.0
    if start is None:
        start = 0.0

    # Parse materials from entity descriptions
    ent_list = entities(doc, scope)
    materials = {}
    for e in ent_list:
        parts = e["description"].split()
        if len(parts) >= 2:
            materials[e["id"]] = parts[1]  # rubber or metal

    sorted_inputs = sorted(inputs, key=lambda x: x["time"])

    state = {}
    outcomes = []

    # Physics parameters estimated from data
    friction = 0.009  # speed decay per frame
    exit_bound = 3.5
    collision_dist = 0.5  # sum of radii threshold

    t = 0
    input_idx = 0
    max_frame = int(horizon) if horizon is not None else 127

    while t <= max_frame:
        # Apply all inputs scheduled for this frame
        while input_idx < len(sorted_inputs) and sorted_inputs[input_idx]["time"] <= t:
            inp = sorted_inputs[input_idx]
            eid = inp["entities"][0]
            state[eid] = {
                "x": inp["fields"].get("x", 0.0),
                "y": inp["fields"].get("y", 0.0),
                "vx": inp["fields"].get("vx", 0.0),
                "vy": inp["fields"].get("vy", 0.0),
                "mat": materials.get(eid, "rubber")
            }
            input_idx += 1

        # Collision detection & resolution
        obj_ids = list(state.keys())
        for i in range(len(obj_ids)):
            for j in range(i+1, len(obj_ids)):
                o1, o2 = obj_ids[i], obj_ids[j]
                s1, s2 = state[o1], state[o2]
                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < collision_dist and dist > 1e-6:
                    nx, ny = dx/dist, dy/dist
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx*nx + dvy*ny

                    if dvn > 0:  # approaching
                        s1["vx"] -= dvn * nx
                        s1["vy"] -= dvn * ny
                        s2["vx"] += dvn * nx
                        s2["vy"] += dvn * ny

                        if t >= start:
                            outcomes.append({
                                "time": float(t),
                                "kind": "collision",
                                "entities": [o1, o2],
                                "value": None,
                                "src": []
                            })

        # Update positions, apply friction, check exits
        for eid in list(state.keys()):
            s = state[eid]
            speed = math.hypot(s["vx"], s["vy"])

            # Apply friction
            if speed > friction:
                factor = (speed - friction) / speed
                s["vx"] *= factor
                s["vy"] *= factor
            elif speed > 0:
                s["vx"] = 0.0
                s["vy"] = 0.0

            s["x"] += s["vx"]
            s["y"] += s["vy"]

            # Check exit
            if abs(s["x"]) > exit_bound or abs(s["y"]) > exit_bound:
                if t >= start:
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": []
                    })
                del state[eid]

        t += 1

    return outcomes

