import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = 127.0
    if start is None:
        start = 0.0

    sorted_inputs = sorted(inputs, key=lambda x: x["time"])
    input_ptr = 0
    n_inputs = len(sorted_inputs)

    state = {}
    outcomes = []

    # Physics parameters estimated from CLEVRER motion logs
    dt = 0.028
    friction = 0.009
    exit_bound = 3.5
    collision_dist = 0.5

    max_t = int(horizon)

    for t in range(max_t + 1):
        # Apply scheduled inputs
        while input_ptr < n_inputs and sorted_inputs[input_ptr]["time"] <= t:
            inp = sorted_inputs[input_ptr]
            eid = inp["entities"][0]
            state[eid] = {
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"]
            }
            input_ptr += 1

        # Collision detection & elastic impulse resolution
        obj_ids = list(state.keys())
        for i in range(len(obj_ids)):
            for j in range(i + 1, len(obj_ids)):
                o1, o2 = obj_ids[i], obj_ids[j]
                s1, s2 = state[o1], state[o2]
                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < collision_dist and dist > 1e-5:
                    nx, ny = dx / dist, dy / dist
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        s1["vx"] -= dvn * nx
                        s1["vy"] -= dvn * ny
                        s2["vx"] += dvn * nx
                        s2["vy"] += dvn * ny

                        if t >= start:
                            outcomes.append({
                                "time": float(t),
                                "kind": "collision",
                                "entities": [o1, o2],
                                "value": None,
                                "src": []
                            })

        # Update positions, apply friction, check exits
        for eid in list(state.keys()):
            s = state[eid]
            speed = math.hypot(s["vx"], s["vy"])

            if speed > friction:
                factor = (speed - friction) / speed
                s["vx"] *= factor
                s["vy"] *= factor
            elif speed > 0:
                s["vx"] = 0.0
                s["vy"] = 0.0

            s["x"] += s["vx"] * dt
            s["y"] += s["vy"] * dt

            if abs(s["x"]) > exit_bound or abs(s["y"]) > exit_bound:
                if t >= start:
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": []
                    })
                del state[eid]

    return outcomes

