import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = 127.0
    if start is None:
        start = 0.0

    # Determine participating entities strictly from inputs
    obj_ids = []
    for inp in inputs:
        if inp["entities"][0] not in obj_ids:
            obj_ids.append(inp["entities"][0])

    # Extract motion log from document to track positions
    scope_node = node_by_title(doc, scope)
    motion_node = None
    for c in children(doc, scope_node):
        if c.get("title", "").endswith(": Motion log"):
            motion_node = c
            break

    motion_data = {}
    if motion_node:
        for row in motion_node["table"]["rows"]:
            f = int(row[0])
            om = re.match(r'(\d+)\s', row[1])
            if om:
                motion_data.setdefault(f, {})[om.group(1)] = (float(row[2]), float(row[3]))

    # Build interpolated position timeline for each object
    timeline = {oid: {} for oid in obj_ids}
    for oid in obj_ids:
        points = []
        for f in range(int(horizon) + 1):
            if f in motion_data and oid in motion_data[f]:
                points.append((f, motion_data[f][oid]))

        if not points:
            # Fallback to input fields if motion log is missing
            for inp in inputs:
                if inp["entities"][0] == oid:
                    t0 = int(inp["time"])
                    timeline[oid][t0] = (inp["fields"]["x"], inp["fields"]["y"])
                    break
            continue

        for t in range(int(start), int(horizon) + 1):
            lower = [p for p in points if p[0] <= t]
            upper = [p for p in points if p[0] > t]
            if lower and not upper:
                timeline[oid][t] = lower[-1][1]
            elif not lower and upper:
                timeline[oid][t] = upper[0][1]
            elif lower and upper:
                f1, (x1, y1) = lower[-1]
                f2, (x2, y2) = upper[0]
                frac = (t - f1) / max(1, f2 - f1)
                timeline[oid][t] = (x1 + (x2 - x1)*frac, y1 + (y2 - y1)*frac)

    outcomes = []
    exited = set()
    collided_at = set()

    # Thresholds estimated from CLEVRER scene bounds and object radii
    exit_bound = 3.6
    collision_dist = 0.65

    for t in range(int(start), int(horizon) + 1):
        active = []
        for oid in obj_ids:
            if oid in exited: 
                continue
            # Object is only active if an input scheduled it to enter by now
            has_input = any(inp["entities"][0] == oid and inp["time"] <= t for inp in inputs)
            if has_input and t in timeline.get(oid, {}):
                active.append((oid, timeline[oid][t]))

        # Check for exits
        for oid, (x, y) in active:
            if abs(x) > exit_bound or abs(y) > exit_bound:
                if oid not in exited:
                    exited.add(oid)
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [oid],
                        "value": None,
                        "src": []
                    })

        # Check for collisions
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                o1, (x1, y1) = active[i]
                o2, (x2, y2) = active[j]
                dist = math.hypot(x1 - x2, y1 - y2)
                if dist < collision_dist:
                    pair = tuple(sorted([o1, o2]))
                    if pair not in collided_at:
                        collided_at.add(pair)
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [o1, o2],
                            "value": None,
                            "src": []
                        })

    return outcomes

