# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    import math
    import re

    DT = 1.0 / 36.0
    DAMPING = 0.996
    COLLISION_DIST = 0.42
    U_MAX = 1.7
    V_MAX = 2.1
    SQRT2 = math.sqrt(2)

    entities_list = entities(doc, scope)
    materials = {}
    for e in entities_list:
        parts = e["description"].split()
        if len(parts) >= 2:
            materials[e["id"]] = parts[1]

    rec_end = recorded_end(doc, scope)
    if rec_end is not None:
        end_frame = int(rec_end)
    else:
        end_frame = 128

    if start is None:
        start_frame = 0
    else:
        start_frame = max(0, int(start))

    if horizon is None:
        horizon_frame = end_frame + 1
    else:
        horizon_frame = int(horizon)

    entries = {}
    for inp in inputs:
        f = int(inp["time"])
        for obj_id in inp["entities"]:
            if (f, obj_id) not in entries:
                entries[(f, obj_id)] = {
                    "x": inp["fields"].get("x", 0),
                    "y": inp["fields"].get("y", 0),
                    "vx": inp["fields"].get("vx", 0),
                    "vy": inp["fields"].get("vy", 0),
                }

    active = {}
    outcomes = []
    recent_collisions = {}

    for frame in range(0, horizon_frame + 1):
        for (f, obj_id), e in entries.items():
            if f == frame and obj_id not in active:
                active[obj_id] = dict(e)

        for obj_id in list(active.keys()):
            s = active[obj_id]
            s["x"] += s["vx"] * DT
            s["y"] += s["vy"] * DT

        obj_list = sorted(active.keys(), key=int)
        for i in range(len(obj_list)):
            for j in range(i + 1, len(obj_list)):
                o1, o2 = obj_list[i], obj_list[j]
                s1, s2 = active[o1], active[o2]

                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST:
                    if dist > 0.001:
                        nx, ny = dx / dist, dy / dist
                    else:
                        nx, ny = 1.0, 0.0

                    vrel_n = (s1["vx"] - s2["vx"]) * nx + (s1["vy"] - s2["vy"]) * ny

                    if vrel_n < 0:
                        pair = tuple(sorted([o1, o2], key=int))
                        if pair in recent_collisions and frame - recent_collisions[pair] < 3:
                            continue

                        m1 = materials.get(o1, "rubber")
                        m2 = materials.get(o2, "rubber")
                        if m1 == "metal" and m2 == "metal":
                            e_rest = 0.9
                        elif m1 == "rubber" and m2 == "rubber":
                            e_rest = 0.5
                        else:
                            e_rest = 0.7

                        impulse = -(1 + e_rest) * vrel_n / 2

                        s1["vx"] += impulse * nx
                        s1["vy"] += impulse * ny
                        s2["vx"] -= impulse * nx
                        s2["vy"] -= impulse * ny

                        overlap = COLLISION_DIST - dist
                        if overlap > 0:
                            s1["x"] += overlap / 2 * nx
                            s1["y"] += overlap / 2 * ny
                            s2["x"] -= overlap / 2 * nx
                            s2["y"] -= overlap / 2 * ny

                        recent_collisions[pair] = frame

                        if frame >= start_frame:
                            outcomes.append({
                                "time": float(frame),
                                "kind": "collision",
                                "entities": list(pair),
                                "value": None,
                                "src": []
                            })

        for obj_id in list(active.keys()):
            s = active[obj_id]
            s["vx"] *= DAMPING
            s["vy"] *= DAMPING

        for obj_id in list(active.keys()):
            s = active[obj_id]
            u = (s["x"] + s["y"]) / SQRT2
            v = (s["y"] - s["x"]) / SQRT2
            if abs(u) > U_MAX or abs(v) > V_MAX:
                del active[obj_id]
                if frame >= start_frame:
                    outcomes.append({
                        "time": float(frame),
                        "kind": "exit",
                        "entities": [obj_id],
                        "value": None,
                        "src": []
                    })

    return outcomes

