# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    import math
    import re

    DT = 1.0 / 36.0
    DAMPING = 0.997
    COLLISION_DIST = 0.42
    U_THRESHOLD = 1.75
    V_THRESHOLD = 2.15
    SQRT2 = math.sqrt(2)

    entities_list = entities(doc, scope)
    materials = {}
    for e in entities_list:
        parts = e["description"].split()
        if len(parts) >= 2:
            materials[e["id"]] = parts[1]

    rec_end = recorded_end(doc, scope)
    if rec_end is not None:
        end_frame = int(rec_end)
    else:
        end_frame = 127

    if horizon is None:
        horizon_frame = end_frame
    else:
        horizon_frame = int(horizon)

    if start is None:
        start_frame = 0
    else:
        start_frame = max(0, int(math.floor(start)))

    # Build entries from inputs
    entries = {}
    for inp in inputs:
        entry_time = int(inp["time"])
        for obj_id in inp["entities"]:
            entries[(entry_time, obj_id)] = {
                "x": inp["fields"].get("x", 0.0),
                "y": inp["fields"].get("y", 0.0),
                "vx": inp["fields"].get("vx", 0.0),
                "vy": inp["fields"].get("vy", 0.0),
            }

    active = {}
    outcomes = []
    recent_collisions = {}

    for frame in range(0, horizon_frame + 1):
        # Activate objects entering at this frame
        for (f, obj_id), state in entries.items():
            if f == frame and obj_id not in active:
                active[obj_id] = dict(state)

        # Update positions
        for obj_id in active:
            s = active[obj_id]
            s["x"] += s["vx"] * DT
            s["y"] += s["vy"] * DT

        # Check collisions
        obj_ids = sorted(active.keys(), key=int)
        for i in range(len(obj_ids)):
            for j in range(i + 1, len(obj_ids)):
                o1, o2 = obj_ids[i], obj_ids[j]
                s1, s2 = active[o1], active[o2]

                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.sqrt(dx*dx + dy*dy)

                if dist < COLLISION_DIST:
                    # Normal direction
                    if dist > 0.0001:
                        nx, ny = dx/dist, dy/dist
                    else:
                        nx, ny = 1.0, 0.0

                    # Relative velocity along normal
                    vrel = (s1["vx"] - s2["vx"])*nx + (s1["vy"] - s2["vy"])*ny

                    # Only collide if approaching
                    if vrel < 0:
                        pair = tuple(sorted([o1, o2], key=int))

                        # Prevent double collisions in same frame or very close frames
                        if pair in recent_collisions and frame - recent_collisions[pair] < 4:
                            continue

                        # Restitution coefficient based on materials
                        mat1 = materials.get(o1, "rubber")
                        mat2 = materials.get(o2, "rubber")
                        if mat1 == "metal" and mat2 == "metal":
                            e_coeff = 0.85
                        elif mat1 == "rubber" and mat2 == "rubber":
                            e_coeff = 0.45
                        else:
                            e_coeff = 0.65

                        # Equal mass collision response
                        impulse = -(1 + e_coeff) * vrel / 2.0

                        s1["vx"] += impulse * nx
                        s1["vy"] += impulse * ny
                        s2["vx"] -= impulse * nx
                        s2["vy"] -= impulse * ny

                        # Separate overlapping objects
                        overlap = COLLISION_DIST - dist
                        if overlap > 0:
                            s1["x"] += (overlap/2) * nx
                            s1["y"] += (overlap/2) * ny
                            s2["x"] -= (overlap/2) * nx
                            s2["y"] -= (overlap/2) * ny

                        recent_collisions[pair] = frame

                        if frame >= start_frame:
                            outcomes.append({
                                "time": float(frame),
                                "kind": "collision",
                                "entities": list(pair),
                                "value": None,
                                "src": []
                            })

        # Apply damping to velocities
        for obj_id in active:
            active[obj_id]["vx"] *= DAMPING
            active[obj_id]["vy"] *= DAMPING

        # Check exit conditions using rotated coordinates
        exiting = []
        for obj_id in active:
            s = active[obj_id]
            u = (s["x"] + s["y"]) / SQRT2
            v = (s["y"] - s["x"]) / SQRT2

            if abs(u) > U_THRESHOLD or abs(v) > V_THRESHOLD:
                exiting.append(obj_id)

        for obj_id in exiting:
            del active[obj_id]
            if frame >= start_frame:
                outcomes.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": []
                })

    return outcomes

