    SQRT2 = math.sqrt(2)
    EXIT_THRESHOLD_U = 2.15
    EXIT_THRESHOLD_V = 2.15

    entities_list = entities(doc, scope)
    materials = {}
    for e in entities_list:
        parts = e["description"].split()
        if len(parts) >= 2:
            materials[e["id"]] = parts[1]

    rec_end = recorded_end(doc, scope)
    if rec_end is not None:
        end_frame = int(rec_end)
    else:
        end_frame = 127

    if horizon is None:
        horizon_frame = end_frame
    else:
        horizon_frame = int(horizon)

    if start is None:
        start_frame = 0
    else:
        start_frame = max(0, int(math.floor(start)))

    # Build entries by frame from inputs
    entries_by_frame = {}
    for inp in inputs:
        frame = int(inp["time"])
        if frame not in entries_by_frame:
            entries_by_frame[frame] = []
        for obj_id in inp["entities"]:
            entries_by_frame[frame].append({
                "obj_id": obj_id,
                "x": inp["fields"].get("x", 0.0),
                "y": inp["fields"].get("y", 0.0),
                "vx": inp["fields"].get("vx", 0.0),
                "vy": inp["fields"].get("vy", 0.0),
            })

    active = {}
    outcomes = []
    recent_collisions = {}

    for frame in range(0, horizon_frame + 1):
        # Activate objects entering at this frame
        if frame in entries_by_frame:
            for entry in entries_by_frame[frame]:
                obj_id = entry["obj_id"]
                if obj_id not in active:
                    active[obj_id] = {
                        "x": entry["x"],
                        "y": entry["y"],
                        "vx": entry["vx"],
                        "vy": entry["vy"],
                    }

        # Update positions
        for obj_id in active:
            s = active[obj_id]
            s["x"] += s["vx"] * DT
            s["y"] += s["vy"] * DT

        # Check collisions
        obj_ids = sorted(active.keys(), key=int)
        for i in range(len(obj_ids)):
            for j in range(i + 1, len(obj_ids)):
                o1, o2 = obj_ids[i], obj_ids[j]
                s1, s2 = active[o1], active[o2]

                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.sqrt(dx*dx + dy*dy)

                if dist < COLLISION_DIST:
                    if dist > 0.0001:
                        nx, ny = dx/dist, dy/dist
                    else:
                        nx, ny = 1.0, 0.0

                    vrel = (s1["vx"] - s2["vx"])*nx + (s1["vy"] - s2["vy"])*ny

                    if vrel < 0:
                        pair = tuple(sorted([o1, o2], key=int))
                        if pair in recent_collisions and frame - recent_collisions[pair] < 4:
                            continue

                        mat1 = materials.get(o1, "rubber")
                        mat2 = materials.get(o2, "rubber")
                        if mat1 == "metal" and mat2 == "metal":
                            e_coeff = 0.85
                        elif mat1 == "rubber" and mat2 == "rubber":
                            e_coeff = 0.6
                        else:
                            e_coeff = 0.7

                        impulse = -(1 + e_coeff) * vrel / 2.0

                        s1["vx"] += impulse * nx
                        s1["vy"] += impulse * ny
                        s2["vx"] -= impulse * nx
                        s2["vy"] -= impulse * ny

                        overlap = COLLISION_DIST - dist
                        if overlap > 0:
                            s1["x"] += (overlap/2) * nx
                            s1["y"] += (overlap/2) * ny
                            s2["x"] -= (overlap/2) * nx
                            s2["y"] -= (overlap/2) * ny

                        recent_collisions[pair] = frame

                        if frame >= start_frame:
                            outcomes.append({
                                "time": float(frame),
                                "kind": "collision",
                                "entities": list(pair),
                                "value": None,
                                "src": []
                            })

        # Apply damping
        for obj_id in active:
            active[obj_id]["vx"] *= DAMPING
            active[obj_id]["vy"] *= DAMPING

        # Check exits using rotated coordinates
        exiting = []
        for obj_id in active:
            s = active[obj_id]
            u = (s["x"] + s["y"]) / SQRT2
            v = (s["y"] - s["x"]) / SQRT2

            if abs(u) > EXIT_THRESHOLD_U or abs(v) > EXIT_THRESHOLD_V:
                exiting.append(obj_id)

        for obj_id in exiting:
            del active[obj_id]
            if frame >= start_frame:
                outcomes.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": []
                })

    return outcomes

import re

def entities(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)

    objects_node = None
    for child in children_nodes:
        if child.get("title", "").endswith(": Objects"):
            objects_node = child
            break

    if objects_node is None:
        return []

    result = []
    for line_idx, line in enumerate(objects_node.get("lines", [])):
        # e.g. "Object 0: gray rubber sphere (color=gray, material=rubber, shape=sphere)"
        m = re.match(r'Object (\d+): (.+?) \(', line)
        if m:
            obj_id = m.group(1)
            description = m.group(2)
            result.append({"id": obj_id, "description": description})

    return result


def recorded_end(doc, scope) -> float or None:
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)

    motion_node = None
    for child in children_nodes:
        if child.get("title", "").endswith(": Motion log"):
            motion_node = child
            break

    if motion_node is None:
        return None

    max_frame = -1
    for row_idx, row in table_rows(motion_node):
        try:
            f = int(row["frame"])
            if f > max_frame:
                max_frame = f
        except (ValueError, KeyError):
            pass

    return float(max_frame) if max_frame >= 0 else None


def _find_node(scope_node, suffix):
    for child in children(doc_global, scope_node):
        if child.get("title", "").endswith(suffix):
            return child
    return None


# We need a way to reference children without capturing doc
# Re-implement helpers inline since doc is passed as parameter

def inputs(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    scope_children = children(doc, scope_node)

    events_node = None
    motion_node = None

    for child in scope_children:
        t = child.get("title", "")
        if t.endswith(": Events"):
            events_node = child
        elif t.endswith(": Motion log"):
            motion_node = child

    if events_node is None:
        return []

    # Build lookup: (frame, obj_id) -> (row_index, row_dict)
    motion_lookup = {}
    if motion_node:
        for row_idx, row in table_rows(motion_node):
            frame = int(row["frame"])
            om = re.match(r'(\d+)\s', row.get("object", ""))
            if om:
                obj_id = om.group(1)
                motion_lookup[(frame, obj_id)] = (row_idx, row)

    inputs_list = []

    for line_idx, line in enumerate(events_node.get("lines", [])):
        fm = re.match(r'Frame (\d+): (.+)', line)
        if not fm:
            continue

        frame = int(fm.group(1))
        rest = fm.group(2)

        # Object is in view when the video begins
        if "is in view when the video begins" in rest:
            om = re.match(r'Object (\d+)\s*\(.+?\)\s*is in view', rest)
            if om:
                obj_id = om.group(1)
                locs = [[events_node["node_id"], line_idx]]
                fields = {}

                ridx, rrow = motion_lookup.get((frame, obj_id), (None, {}))
                if rrow:
                    for col in ["x", "y", "vx", "vy", "speed"]:
                        try:
                            fields[col] = float(rrow[col])
                        except (KeyError, ValueError):
                            pass
                    locs.append([motion_node["node_id"], ridx, ["frame", "object", "x", "y", "vx", "vy", "speed"]])

                inputs_list.append({
                    "id": f"init_{obj_id}",
                    "time": float(frame),
                    "kind": "initial_presence",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": locs
                })

        # Object enters the scene
        elif "enters the scene" in rest:
            om = re.match(r'Object (\d+)\s*\(.+?\)\s*enters the scene', rest)
            if om:
                obj_id = om.group(1)
                locs = [[events_node["node_id"], line_idx]]
                fields = {}

                ridx, rrow = motion_lookup.get((frame, obj_id), (None, {}))
                if rrow:
                    for col in ["x", "y", "vx", "vy", "speed"]:
                        try:
                            fields[col] = float(rrow[col])
                        except (KeyError, ValueError):
                            pass
                    locs.append([motion_node["node_id"], ridx, ["frame", "object", "x", "y", "vx", "vy", "speed"]])

                inputs_list.append({
                    "id": f"entry_{obj_id}_{frame}",
                    "time": float(frame),
                    "kind": "entry",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": locs
                })

    return inputs_list


def outcomes(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    scope_children = children(doc, scope_node)

    events_node = None

    for child in scope_children:
        if child.get("title", "").endswith(": Events"):
            events_node = child
            break

    if events_node is None:
        return []

    outcomes_list = []

    for line_idx, line in enumerate(events_node.get("lines", [])):
        fm = re.match(r'Frame (\d+): (.+)', line)
        if not fm:
            continue

        frame = int(fm.group(1))
        rest = fm.group(2)

        # Collision
        cm = re.match(r'Object (\d+)\s*\(.+?\)\s*and\s*Object (\d+)\s*\(.+?\)\s*collide', rest)
        if cm:
            outcomes_list.append({
                "time": float(frame),
                "kind": "collision",
                "entities": [cm.group(1), cm.group(2)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
            continue

        # Exit
        em = re.match(r'Object (\d+)\s*\(.+?\)\s*exits the scene', rest)
        if em:
            outcomes_list.append({
                "time": float(frame),
                "kind": "exit",
                "entities": [em.group(1)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })

    return outcomes_list


