import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # Determine simulation bounds
    if horizon is None:
        horizon = recorded_end(doc, scope)
    if horizon is None:
        horizon = 127.0

    # Get entity materials
    ents = entities(doc, scope)
    ent_mat = {}
    for e in ents:
        desc = e["description"]
        ent_mat[e["id"]] = "metal" if "metal" in desc else "rubber"

    # Physics constants estimated from CLEVRER benchmark data
    FRICTION_RUBBER = 0.013
    FRICTION_METAL = 0.004
    MASS_RUBBER = 1.0
    MASS_METAL = 2.0
    COLLISION_DIST = 0.6
    EXIT_BOUND = 4.0

    # Group inputs by time for easy processing
    inputs_by_time = defaultdict(list)
    for inp in inputs:
        inputs_by_time[inp["time"]].append(inp)

    sim_start = min(inputs_by_time.keys()) if inputs_by_time else 0
    if start is None:
        start = sim_start

    # State tracking: obj_id -> {x, y, vx, vy, material, active}
    state = {}

    # Initialize state from inputs at simulation start
    for inp in inputs_by_time.get(sim_start, []):
        for eid in inp["entities"]:
            state[eid] = {
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"],
                "material": ent_mat.get(eid, "rubber"),
                "active": True
            }

    outcomes = []
    collided_this_frame = set()

    t = int(sim_start)
    while t <= horizon:
        # Process object entries at this frame
        for inp in inputs_by_time.get(t, []):
            if inp["kind"] == "entry":
                for eid in inp["entities"]:
                    state[eid] = {
                        "x": inp["fields"]["x"],
                        "y": inp["fields"]["y"],
                        "vx": inp["fields"]["vx"],
                        "vy": inp["fields"]["vy"],
                        "material": ent_mat.get(eid, "rubber"),
                        "active": True
                    }

        # Update positions and apply friction
        for eid, s in state.items():
            if not s["active"]:
                continue

            s["x"] += s["vx"]
            s["y"] += s["vy"]

            speed = math.hypot(s["vx"], s["vy"])
            if speed > 0:
                fric = FRICTION_RUBBER if s["material"] == "rubber" else FRICTION_METAL
                if speed <= fric:
                    s["vx"] = 0.0
                    s["vy"] = 0.0
                else:
                    scale = (speed - fric) / speed
                    s["vx"] *= scale
                    s["vy"] *= scale

            # Check if object exits the scene bounds
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                s["active"] = False
                if t >= start:
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": []
                    })

        # Detect and resolve collisions
        active_ids = [eid for eid, s in state.items() if s["active"]]
        for i in range(len(active_ids)):
            for j in range(i + 1, len(active_ids)):
                id1, id2 = active_ids[i], active_ids[j]
                pair = tuple(sorted([id1, id2]))
                if pair in collided_this_frame:
                    continue

                s1, s2 = state[id1], state[id2]
                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-4:
                    # Collision normal
                    nx = dx / dist
                    ny = dy / dist

                    # Masses based on material
                    m1 = MASS_METAL if s1["material"] == "metal" else MASS_RUBBER
                    m2 = MASS_METAL if s2["material"] == "metal" else MASS_RUBBER

                    # Relative velocity along normal
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    # Only resolve if moving towards each other
                    if dvn > 0:
                        # Elastic collision impulse
                        impulse = 2.0 * dvn / (1.0/m1 + 1.0/m2)
                        s1["vx"] -= impulse/m1 * nx
                        s1["vy"] -= impulse/m1 * ny
                        s2["vx"] += impulse/m2 * nx
                        s2["vy"] += impulse/m2 * ny

                        # Separate objects slightly to prevent sticking
                        sep = (COLLISION_DIST - dist) * 0.5 + 0.01
                        s1["x"] += nx * sep
                        s1["y"] += ny * sep
                        s2["x"] -= nx * sep
                        s2["y"] -= ny * sep

                        collided_this_frame.add(pair)
                        if t >= start:
                            outcomes.append({
                                "time": float(t),
                                "kind": "collision",
                                "entities": list(pair),
                                "value": None,
                                "src": []
                            })

        collided_this_frame.clear()
        t += 1

    return outcomes

