        desc = e["description"]
        ent_mat[e["id"]] = "metal" if "metal" in desc else "rubber"
    return ent_mat

def estimate_physics_params(doc, all_scopes=None):
    """Estimate physics parameters from available scope data."""
    if all_scopes is None:
        all_scopes = [n["title"] for n in doc["nodes"] if n.get("title", "").startswith("Video ") and n.get("kind") == "text"]

    friction_rates_rubber = []
    friction_rates_metal = []
    collision_dists = []
    exit_bounds_seen = []

    for scope in all_scopes[:10]:
        scope_node = node_by_title(doc, scope)
        children_nodes = children(doc, scope_node)

        motion_node = None
        objects_node = None
        events_node = None

        for child in children_nodes:
            t = child.get("title", "")
            if t.endswith(": Motion log"):
                motion_node = child
            elif t.endswith(": Objects"):
                objects_node = child
            elif t.endswith(": Events"):
                events_node = child

        if not motion_node or not objects_node:
            continue

        # Get object materials
        obj_materials = {}
        for line in objects_node.get("lines", []):
            m = re.match(r'Object (\d+): (.+?) \(color=.+?, material=(\w+)', line)
            if m:
                obj_materials[m.group(1)] = m.group(3)

        # Build motion history per object
        motion_history = defaultdict(list)
        for _, row in table_rows(motion_node):
            frame = int(row["frame"])
            obj_match = re.match(r'(\d+)\s', row["object"])
            if obj_match:
                obj_id = obj_match.group(1)
                motion_history[obj_id].append({
                    "frame": frame,
                    "x": float(row["x"]),
                    "y": float(row["y"]),
                    "vx": float(row["vx"]),
                    "vy": float(row["vy"]),
                    "speed": float(row["speed"])
                })

        # Sort by frame
        for obj_id in motion_history:
            motion_history[obj_id].sort(key=lambda r: r["frame"])

        # Estimate friction from speed changes
        for obj_id, history in motion_history.items():
            mat = obj_materials.get(obj_id, "rubber")
            for i in range(1, len(history)):
                h1, h2 = history[i-1], history[i]
                dt = h2["frame"] - h1["frame"]
                if dt <= 0:
                    continue
                s1, s2 = h1["speed"], h2["speed"]
                if s1 > 0.1:  # Only look at moving objects
                    decel = (s1 - s2) / dt
                    if decel > 0:  # Should be decelerating due to friction
                        if mat == "rubber":
                            friction_rates_rubber.append(decel)
                        else:
                            friction_rates_metal.append(decel)

        # Estimate exit bounds from events
        if events_node:
            for line in events_node.get("lines", []):
                em = re.match(r'Frame (\d+): Object (\d+)\s*\(.*?\)\s*exits the scene', line)
                if em:
                    frame = int(em.group(1))
                    obj_id = em.group(2)
                    # Find position just before exit
                    if obj_id in motion_history:
                        for h in motion_history[obj_id]:
                            if h["frame"] <= frame:
                                exit_bounds_seen.append(max(abs(h["x"]), abs(h["y"])))

        # Estimate collision distances from collision events
        if events_node:
            collisions = []
            for line in events_node.get("lines", []):
                cm = re.match(r'Frame (\d+): Object (\d+)\s*\(.*?\)\s*and\s*Object (\d+)\s*\(.*?\)\s*collide', line)
                if cm:
                    collisions.append({
                        "frame": int(cm.group(1)),
                        "obj1": cm.group(2),
                        "obj2": cm.group(3)
                    })

            for col in collisions:
                f, o1, o2 = col["frame"], col["obj1"], col["obj2"]
                if o1 in motion_history and o2 in motion_history:
                    # Find closest frame <= collision frame for both
                    pos1 = None
                    pos2 = None
                    for h in motion_history[o1]:
                        if h["frame"] <= f:
                            pos1 = (h["x"], h["y"])
                        else:
                            break
                    for h in motion_history[o2]:
                        if h["frame"] <= f:
                            pos2 = (h["x"], h["y"])
                        else:
                            break
                    if pos1 and pos2:
                        dist = math.hypot(pos1[0]-pos2[0], pos1[1]-pos2[1])
                        collision_dists.append(dist)

    # Compute averages
    friction_rubber = sum(friction_rates_rubber) / len(friction_rates_rubber) if friction_rates_rubber else 0.012
    friction_metal = sum(friction_rates_metal) / len(friction_rates_metal) if friction_rates_metal else 0.003
    collision_dist = sum(collision_dists) / len(collision_dists) if collision_dists else 0.55
    exit_bound = sum(exit_bounds_seen) / len(exit_bounds_seen) if exit_bounds_seen else 3.5

    # Clamp to reasonable values
    friction_rubber = max(0.005, min(friction_rubber, 0.03))
    friction_metal = max(0.001, min(friction_metal, 0.01))
    collision_dist = max(0.3, min(collision_dist, 0.8))
    exit_bound = max(3.0, min(exit_bound, 5.0))

    return {
        "friction_rubber": friction_rubber,
        "friction_metal": friction_metal,
        "collision_dist": collision_dist,
        "exit_bound": exit_bound
    }

