_cached_physics = None

def get_physics_params(doc):
    global _cached_physics
    if _cached_physics is None:
        _cached_physics = estimate_physics_params(doc)
    return _cached_physics

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    global _cached_physics
    _cached_physics = None  # Reset cache to recalculate if needed

    # Determine horizon
    if horizon is None:
        horizon = recorded_end(doc, scope)
    if horizon is None:
        horizon = 127.0

    # Get entity materials
    ent_mat = get_entity_materials(doc, scope)

    # Get physics parameters
    phys = get_physics_params(doc)
    FRICTION_RUBBER = phys["friction_rubber"]
    FRICTION_METAL = phys["friction_metal"]
    COLLISION_DIST = phys["collision_dist"]
    EXIT_BOUND = phys["exit_bound"]

    station_threshold = params.get("stationary_threshold", 0.1)

    # Sort inputs by time
    sorted_inputs = sorted(inputs, key=lambda x: x["time"])

    if not sorted_inputs:
        return []

    # Determine simulation start
    sim_start = sorted_inputs[0]["time"]
    if start is None:
        start = sim_start

    # State: obj_id -> {x, y, vx, vy, material, active, entered_at}
    state = {}
    active_entities = set()

    # Track which collisions have been reported (by entity pair)
    reported_collisions = set()
    reported_exits = set()

    outcomes = []

    # Phase 1: Replay from sim_start to start to initialize state
    t = int(sim_start)
    current_inputs_idx = 0

    # First, initialize from inputs at sim_start
    for inp in sorted_inputs:
        if inp["time"] == sim_start:
            for eid in inp["entities"]:
                state[eid] = {
                    "x": inp["fields"]["x"],
                    "y": inp["fields"]["y"],
                    "vx": inp["fields"]["vx"],
                    "vy": inp["fields"]["vy"],
                    "material": ent_mat.get(eid, "rubber"),
                    "active": True,
                    "entered_at": inp["time"]
                }
                active_entities.add(eid)

    # Replay physics up to start
    while t < start:
        # Process entries that happen at this frame
        for inp in sorted_inputs:
            if inp["time"] == t and inp["kind"] == "entry":
                for eid in inp["entities"]:
                    state[eid] = {
                        "x": inp["fields"]["x"],
                        "y": inp["fields"]["y"],
                        "vx": inp["fields"]["vx"],
                        "vy": inp["fields"]["vy"],
                        "material": ent_mat.get(eid, "rubber"),
                        "active": True,
                        "entered_at": t
                    }
                    active_entities.add(eid)

        # Update positions and apply friction
        for eid in list(active_entities):
            s = state.get(eid)
            if not s or not s["active"]:
                continue

            s["x"] += s["vx"]
            s["y"] += s["vy"]

            speed = math.hypot(s["vx"], s["vy"])
            fric = FRICTION_RUBBER if s["material"] == "rubber" else FRICTION_METAL

            if speed > 0:
                if speed <= fric:
                    s["vx"] = 0.0
                    s["vy"] = 0.0
                else:
                    scale = (speed - fric) / speed
                    s["vx"] *= scale
                    s["vy"] *= scale

            # Check exit (during replay, just mark but don't record)
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                s["active"] = False
                active_entities.discard(eid)

        # Collision detection during replay (for state update, not recording)
        active_list = [eid for eid in active_entities if state.get(eid, {}).get("active", False)]
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                id1, id2 = active_list[i], active_list[j]
                s1, s2 = state[id1], state[id2]

                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-4:
                    # Collision normal
                    nx, ny = dx / dist, dy / dist

                    # Masses: metal=2, rubber=1
                    m1 = 2.0 if s1["material"] == "metal" else 1.0
                    m2 = 2.0 if s2["material"] == "metal" else 1.0

                    # Relative velocity along normal
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:  # Moving towards each other
                        # Elastic collision
                        impulse = 2.0 * dvn / (1.0/m1 + 1.0/m2)
                        s1["vx"] -= impulse/m1 * nx
                        s1["vy"] -= impulse/m1 * ny
                        s2["vx"] += impulse/m2 * nx
                        s2["vy"] += impulse/m2 * ny

                        # Separate objects
                        sep = (COLLISION_DIST - dist) * 0.5 + 0.01
                        s1["x"] += nx * sep
                        s1["y"] += ny * sep
                        s2["x"] -= nx * sep
                        s2["y"] -= ny * sep

        t += 1

    # Phase 2: Simulate from start to horizon, recording outcomes
    while t <= int(horizon):
        # Process entries at this frame
        for inp in sorted_inputs:
            if inp["time"] == t and inp["kind"] == "entry":
                for eid in inp["entities"]:
                    state[eid] = {
                        "x": inp["fields"]["x"],
                        "y": inp["fields"]["y"],
                        "vx": inp["fields"]["vx"],
                        "vy": inp["fields"]["vy"],
                        "material": ent_mat.get(eid, "rubber"),
                        "active": True,
                        "entered_at": t
                    }
                    active_entities.add(eid)

        # Update positions and apply friction
        for eid in list(active_entities):
            s = state.get(eid)
            if not s or not s["active"]:
                continue

            s["x"] += s["vx"]
            s["y"] += s["vy"]

            speed = math.hypot(s["vx"], s["vy"])
            fric = FRICTION_RUBBER if s["material"] == "rubber" else FRICTION_METAL

            if speed > 0:
                if speed <= fric:
                    s["vx"] = 0.0
                    s["vy"] = 0.0
                else:
                    scale = (speed - fric) / speed
                    s["vx"] *= scale
                    s["vy"] *= scale

            # Check exit
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                s["active"] = False
                if eid not in reported_exits:
                    reported_exits.add(eid)
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [eid],
                        "value": None,
                        "src": []
                    })

        # Collision detection and resolution
        active_list = [eid for eid in active_entities if state.get(eid, {}).get("active", False)]
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                id1, id2 = active_list[i], active_list[j]
                s1, s2 = state[id1], state[id2]

                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-4:
                    pair = tuple(sorted([id1, id2]))

                    # Collision normal
                    nx, ny = dx / dist, dy / dist

                    # Masses
                    m1 = 2.0 if s1["material"] == "metal" else 1.0
                    m2 = 2.0 if s2["material"] == "metal" else 1.0

                    # Relative velocity along normal
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        # Elastic collision
                        impulse = 2.0 * dvn / (1.0/m1 + 1.0/m2)
                        s1["vx"] -= impulse/m1 * nx
                        s1["vy"] -= impulse/m1 * ny
                        s2["vx"] += impulse/m2 * nx
                        s2["vy"] += impulse/m2 * ny

                        # Separate
                        sep = (COLLISION_DIST - dist) * 0.5 + 0.01
                        s1["x"] += nx * sep
                        s1["y"] += ny * sep
                        s2["x"] -= nx * sep
                        s2["y"] -= ny * sep

                        if pair not in reported_collisions:
                            reported_collisions.add(pair)
                            outcomes.append({
                                "time": float(t),
                                "kind": "collision",
                                "entities": list(pair),
                                "value": None,
                                "src": []
                            })

        t += 1

    return outcomes

import re

def entities(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)

    objects_node = None
    for child in children_nodes:
        if child.get("title", "").endswith(": Objects"):
            objects_node = child
            break

    if objects_node is None:
        return []

    result = []
    for line_idx, line in enumerate(objects_node.get("lines", [])):
        # e.g. "Object 0: gray rubber sphere (color=gray, material=rubber, shape=sphere)"
        m = re.match(r'Object (\d+): (.+?) \(', line)
        if m:
            obj_id = m.group(1)
            description = m.group(2)
            result.append({"id": obj_id, "description": description})

    return result


def recorded_end(doc, scope) -> float or None:
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)

    motion_node = None
    for child in children_nodes:
        if child.get("title", "").endswith(": Motion log"):
            motion_node = child
            break

    if motion_node is None:
        return None

    max_frame = -1
    for row_idx, row in table_rows(motion_node):
        try:
            f = int(row["frame"])
            if f > max_frame:
                max_frame = f
        except (ValueError, KeyError):
            pass

    return float(max_frame) if max_frame >= 0 else None


def _find_node(scope_node, suffix):
    for child in children(doc_global, scope_node):
        if child.get("title", "").endswith(suffix):
            return child
    return None


# We need a way to reference children without capturing doc
# Re-implement helpers inline since doc is passed as parameter

def inputs(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    scope_children = children(doc, scope_node)

    events_node = None
    motion_node = None

    for child in scope_children:
        t = child.get("title", "")
        if t.endswith(": Events"):
            events_node = child
        elif t.endswith(": Motion log"):
            motion_node = child

    if events_node is None:
        return []

    # Build lookup: (frame, obj_id) -> (row_index, row_dict)
    motion_lookup = {}
    if motion_node:
        for row_idx, row in table_rows(motion_node):
            frame = int(row["frame"])
            om = re.match(r'(\d+)\s', row.get("object", ""))
            if om:
                obj_id = om.group(1)
                motion_lookup[(frame, obj_id)] = (row_idx, row)

    inputs_list = []

    for line_idx, line in enumerate(events_node.get("lines", [])):
        fm = re.match(r'Frame (\d+): (.+)', line)
        if not fm:
            continue

        frame = int(fm.group(1))
        rest = fm.group(2)

        # Object is in view when the video begins
        if "is in view when the video begins" in rest:
            om = re.match(r'Object (\d+)\s*\(.+?\)\s*is in view', rest)
            if om:
                obj_id = om.group(1)
                locs = [[events_node["node_id"], line_idx]]
                fields = {}

                ridx, rrow = motion_lookup.get((frame, obj_id), (None, {}))
                if rrow:
                    for col in ["x", "y", "vx", "vy", "speed"]:
                        try:
                            fields[col] = float(rrow[col])
                        except (KeyError, ValueError):
                            pass
                    locs.append([motion_node["node_id"], ridx, ["frame", "object", "x", "y", "vx", "vy", "speed"]])

                inputs_list.append({
                    "id": f"init_{obj_id}",
                    "time": float(frame),
                    "kind": "initial_presence",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": locs
                })

        # Object enters the scene
        elif "enters the scene" in rest:
            om = re.match(r'Object (\d+)\s*\(.+?\)\s*enters the scene', rest)
            if om:
                obj_id = om.group(1)
                locs = [[events_node["node_id"], line_idx]]
                fields = {}

                ridx, rrow = motion_lookup.get((frame, obj_id), (None, {}))
                if rrow:
                    for col in ["x", "y", "vx", "vy", "speed"]:
                        try:
                            fields[col] = float(rrow[col])
                        except (KeyError, ValueError):
                            pass
                    locs.append([motion_node["node_id"], ridx, ["frame", "object", "x", "y", "vx", "vy", "speed"]])

                inputs_list.append({
                    "id": f"entry_{obj_id}_{frame}",
                    "time": float(frame),
                    "kind": "entry",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": locs
                })

    return inputs_list


def outcomes(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    scope_children = children(doc, scope_node)

    events_node = None

    for child in scope_children:
        if child.get("title", "").endswith(": Events"):
            events_node = child
            break

    if events_node is None:
        return []

    outcomes_list = []

    for line_idx, line in enumerate(events_node.get("lines", [])):
        fm = re.match(r'Frame (\d+): (.+)', line)
        if not fm:
            continue

        frame = int(fm.group(1))
        rest = fm.group(2)

        # Collision
        cm = re.match(r'Object (\d+)\s*\(.+?\)\s*and\s*Object (\d+)\s*\(.+?\)\s*collide', rest)
        if cm:
            outcomes_list.append({
                "time": float(frame),
                "kind": "collision",
                "entities": [cm.group(1), cm.group(2)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
            continue

        # Exit
        em = re.match(r'Object (\d+)\s*\(.+?\)\s*exits the scene', rest)
        if em:
            outcomes_list.append({
                "time": float(frame),
                "kind": "exit",
                "entities": [em.group(1)],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })

    return outcomes_list


