import re
import math
from collections import defaultdict

def get_entity_materials(doc, scope):
    """Extract material info for each entity from the document."""
    ents = entities(doc, scope)
    ent_mat = {}
    for e in ents:
        desc = e["description"]
        ent_mat[e["id"]] = "metal" if "metal" in desc else "rubber"
    return ent_mat

def estimate_physics_params(doc):
    """Estimate physics parameters from available scope data."""
    friction_rates_rubber = []
    friction_rates_metal = []
    exit_bounds_seen = []

    for node in doc["nodes"]:
        title = node.get("title", "")
        if not title.startswith("Video ") or not title.endswith(": Objects"):
            continue
        scope_name = title.rsplit(":", 1)[0].strip()
        scope_node = node_by_title(doc, scope_name)
        children_nodes = children(doc, scope_node)

        motion_node = None
        events_node = None

        for child in children_nodes:
            t = child.get("title", "")
            if t.endswith(": Motion log"):
                motion_node = child
            elif t.endswith(": Events"):
                events_node = child

        if not motion_node:
            continue

        # Get object materials
        obj_materials = {}
        for line in node.get("lines", []):
            m = re.match(r'Object (\d+): .+? \(color=.+?, material=(\w+)', line)
            if m:
                obj_materials[m.group(1)] = m.group(2)

        # Build motion history per object
        motion_history = defaultdict(list)
        for _, row in table_rows(motion_node):
            frame = int(row["frame"])
            obj_match = re.match(r'(\d+)\s', row["object"])
            if obj_match:
                obj_id = obj_match.group(1)
                motion_history[obj_id].append({
                    "frame": frame,
                    "x": float(row["x"]),
                    "y": float(row["y"]),
                    "vx": float(row["vx"]),
                    "vy": float(row["vy"]),
                    "speed": float(row["speed"])
                })

        for obj_id in motion_history:
            motion_history[obj_id].sort(key=lambda r: r["frame"])

        # Estimate friction from speed changes
        for obj_id, history in motion_history.items():
            mat = obj_materials.get(obj_id, "rubber")
            for i in range(1, len(history)):
                h1, h2 = history[i-1], history[i]
                dt = h2["frame"] - h1["frame"]
                if dt <= 0:
                    continue
                s1, s2 = h1["speed"], h2["speed"]
                if s1 > 0.1:
                    decel = (s1 - s2) / dt
                    if decel > 0:
                        if mat == "rubber":
                            friction_rates_rubber.append(decel)
                        else:
                            friction_rates_metal.append(decel)

        # Estimate exit bounds
        if events_node:
            for line in events_node.get("lines", []):
                em = re.match(r'Frame (\d+): Object (\d+)\s*\(.*?\)\s*exits the scene', line)
                if em:
                    frame = int(em.group(1))
                    obj_id = em.group(2)
                    if obj_id in motion_history:
                        for h in motion_history[obj_id]:
                            if h["frame"] <= frame:
                                exit_bounds_seen.append(max(abs(h["x"]), abs(h["y"])))

    friction_rubber = sum(friction_rates_rubber) / len(friction_rates_rubber) if friction_rates_rubber else 0.012
    friction_metal = sum(friction_rates_metal) / len(friction_rates_metal) if friction_rates_metal else 0.003
    exit_bound = sum(exit_bounds_seen) / len(exit_bounds_seen) if exit_bounds_seen else 3.5

    friction_rubber = max(0.005, min(friction_rubber, 0.03))
    friction_metal = max(0.001, min(friction_metal, 0.01))
    exit_bound = max(2.5, min(exit_bound, 4.5))

    return {
        "friction_rubber": friction_rubber,
        "friction_metal": friction_metal,
        "exit_bound": exit_bound,
        "collision_dist": 0.55
    }

_cached_physics = None

def get_physics_params(doc):
