def simulate(doc, scope, inputs, params, start=None, horizon=None):
    global _cached_physics
    _cached_physics = None

    if horizon is None:
        horizon = recorded_end(doc, scope)
    if horizon is None:
        horizon = 127.0

    ent_mat = get_entity_materials(doc, scope)
    phys = get_physics_params(doc)
    FRICTION_RUBBER = phys["friction_rubber"]
    FRICTION_METAL = phys["friction_metal"]
    COLLISION_DIST = phys["collision_dist"]
    EXIT_BOUND = phys["exit_bound"]

    station_threshold = params.get("stationary_threshold", 0.1)

    # Group inputs by frame (use int(time))
    inputs_by_frame = defaultdict(list)
    for inp in inputs:
        frame = int(inp["time"])
        inputs_by_frame[frame].append(inp)

    if not inputs_by_frame:
        return []

    all_frames = sorted(inputs_by_frame.keys())
    sim_start = all_frames[0]

    if start is None:
        start = float(sim_start)

    # State: obj_id -> {x, y, vx, vy, material, active}
    state = {}
    active_entities = set()

    def process_entries(frame):
        for inp in inputs_by_frame.get(frame, []):
            if inp["kind"] == "entry":
                for eid in inp["entities"]:
                    state[eid] = {
                        "x": inp["fields"]["x"],
                        "y": inp["fields"]["y"],
                        "vx": inp["fields"]["vx"],
                        "vy": inp["fields"]["vy"],
                        "material": ent_mat.get(eid, "rubber"),
                        "active": True
                    }
                    active_entities.add(eid)

    def process_initial(frame):
        for inp in inputs_by_frame.get(frame, []):
            if inp["kind"] == "initial_presence":
                for eid in inp["entities"]:
                    state[eid] = {
                        "x": inp["fields"]["x"],
                        "y": inp["fields"]["y"],
                        "vx": inp["fields"]["vx"],
                        "vy": inp["fields"]["vy"],
                        "material": ent_mat.get(eid, "rubber"),
                        "active": True
                    }
                    active_entities.add(eid)

    def step(frame):
        # Update positions
        for eid in list(active_entities):
            s = state.get(eid)
            if not s or not s["active"]:
                continue
            s["x"] += s["vx"]
            s["y"] += s["vy"]

            speed = math.hypot(s["vx"], s["vy"])
            fric = FRICTION_RUBBER if s["material"] == "rubber" else FRICTION_METAL

            if speed > 0:
                if speed <= fric:
                    s["vx"] = 0.0
                    s["vy"] = 0.0
                else:
                    scale = (speed - fric) / speed
                    s["vx"] *= scale
                    s["vy"] *= scale

    def detect_collisions(frame):
        active_list = [eid for eid in active_entities if state.get(eid, {}).get("active", False)]
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                id1, id2 = active_list[i], active_list[j]
                s1, s2 = state[id1], state[id2]

                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-6:
                    nx, ny = dx / dist, dy / dist

                    m1 = 2.0 if s1["material"] == "metal" else 1.0
                    m2 = 2.0 if s2["material"] == "metal" else 1.0

                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        impulse = 2.0 * dvn / (1.0/m1 + 1.0/m2)
                        s1["vx"] -= impulse/m1 * nx
                        s1["vy"] -= impulse/m1 * ny
                        s2["vx"] += impulse/m2 * nx
                        s2["vy"] += impulse/m2 * ny

                        sep = (COLLISION_DIST - dist) * 0.5 + 0.01
                        s1["x"] += nx * sep
                        s1["y"] += ny * sep
                        s2["x"] -= nx * sep
                        s2["y"] -= ny * sep

