    start_frame = int(start)

    # Process initial state at sim_start
    process_initial(sim_start)
    process_entries(sim_start)

    t = sim_start + 1
    while t < start_frame:
        process_entries(t)
        step(t)
        detect_collisions(t)

        # Check exits during replay (don't record)
        for eid in list(active_entities):
            s = state.get(eid)
            if s and s["active"]:
                if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                    s["active"] = False
                    active_entities.discard(eid)
        t += 1

    # Now simulate from start_frame to horizon, recording outcomes
    outcomes = []
    reported_collisions = set()
    reported_exits = set()

    t = start_frame
    horizon_frame = int(math.ceil(horizon))

    while t <= horizon_frame:
        process_entries(t)
        step(t)
        detect_collisions(t)

        # Check exits
        for eid in list(active_entities):
            s = state.get(eid)
            if s and s["active"]:
                if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                    s["active"] = False
                    if eid not in reported_exits:
                        reported_exits.add(eid)
                        outcomes.append({
                            "time": float(t),
                            "kind": "exit",
                            "entities": [eid],
                            "value": None,
                            "src": []
                        })

        # Check collisions
        active_list = [eid for eid in active_entities if state.get(eid, {}).get("active", False)]
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                id1, id2 = active_list[i], active_list[j]
                pair = tuple(sorted([id1, id2]))

                s1, s2 = state[id1], state[id2]
                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-6:
