def simulate(doc, scope, inputs, params, start=None, horizon=None):
    global _cached_physics
    _cached_physics = None

    if horizon is None:
        horizon = recorded_end(doc, scope)
    if horizon is None:
        horizon = 127.0

    ent_mat = get_entity_materials(doc, scope)

    # Physics constants estimated from CLEVRER benchmark data
    K = 1.0 / 35.0  # Position update scaling factor (~0.02857)
    FRICTION_RUBBER = 0.0125  # Speed reduction per frame for rubber
    FRICTION_METAL = 0.006    # Speed reduction per frame for metal
    EXIT_BOUND = 4.0          # Objects exit when |x| > 4 or |y| > 4
    COLLISION_DIST = 0.55     # Collision distance threshold

    station_threshold = params.get("stationary_threshold", 0.1)

    # Group inputs by frame
    inputs_by_frame = defaultdict(list)
    for inp in inputs:
        frame = int(inp["time"])
        inputs_by_frame[frame].append(inp)

    if not inputs_by_frame:
        return []

    all_frames = sorted(inputs_by_frame.keys())
    sim_start = all_frames[0]

    if start is None:
        start = float(sim_start)

    start_frame = int(start)

    # State tracking
    state = {}
    active_entities = set()

    def process_inputs_at(frame):
        for inp in inputs_by_frame.get(frame, []):
            for eid in inp["entities"]:
                state[eid] = {
                    "x": inp["fields"]["x"],
                    "y": inp["fields"]["y"],
                    "vx": inp["fields"]["vx"],
                    "vy": inp["fields"]["vy"],
                    "material": ent_mat.get(eid, "rubber"),
                    "active": True
                }
                active_entities.add(eid)

    def apply_physics():
        for eid in list(active_entities):
            s = state.get(eid)
            if not s or not s["active"]:
                continue
            # Update position with scaling factor
            s["x"] += s["vx"] * K
            s["y"] += s["vy"] * K

            # Apply friction
            speed = math.hypot(s["vx"], s["vy"])
            fric = FRICTION_RUBBER if s["material"] == "rubber" else FRICTION_METAL

            if speed > 0:
                if speed <= fric:
                    s["vx"] = 0.0
                    s["vy"] = 0.0
                else:
                    scale = (speed - fric) / speed
                    s["vx"] *= scale
                    s["vy"] *= scale

    def handle_collisions():
        active_list = [eid for eid in active_entities if state.get(eid, {}).get("active", False)]
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                id1, id2 = active_list[i], active_list[j]
                s1, s2 = state[id1], state[id2]

                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-6:
                    nx, ny = dx / dist, dy / dist

                    m1 = 2.0 if s1["material"] == "metal" else 1.0
                    m2 = 2.0 if s2["material"] == "metal" else 1.0

                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        impulse = 2.0 * dvn / (1.0/m1 + 1.0/m2)
                        s1["vx"] -= impulse/m1 * nx
                        s1["vy"] -= impulse/m1 * ny
                        s2["vx"] += impulse/m2 * nx
                        s2["vy"] += impulse/m2 * ny

                        sep = (COLLISION_DIST - dist) * 0.5 + 0.01
                        s1["x"] += nx * sep
                        s1["y"] += ny * sep
                        s2["x"] -= nx * sep
                        s2["y"] -= ny * sep

    def check_exits(outcomes, reported_exits):
        for eid in list(active_entities):
            s = state.get(eid)
            if s and s["active"]:
                if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                    s["active"] = False
                    if eid not in reported_exits:
                        reported_exits.add(eid)
                        return eid
        return None

    # Phase 1: Replay from sim_start to start_frame (initialize state)
    # Process inputs at sim_start
    process_inputs_at(sim_start)

    t = sim_start + 1
    while t < start_frame:
        process_inputs_at(t)
        apply_physics()
        handle_collisions()

        # Check exits during replay (don't record, just deactivate)
        for eid in list(active_entities):
            s = state.get(eid)
            if s and s["active"]:
                if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                    s["active"] = False
                    active_entities.discard(eid)
        t += 1

    # Phase 2: Simulate from start_frame to horizon, recording outcomes
    outcomes = []
    reported_collisions = set()
    reported_exits = set()

    t = start_frame
    horizon_frame = int(math.ceil(horizon))

    while t <= horizon_frame:
        process_inputs_at(t)
        apply_physics()
        handle_collisions()

        # Check exits and record
        for eid in list(active_entities):
            s = state.get(eid)
            if s and s["active"]:
                if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                    s["active"] = False
                    if eid not in reported_exits:
                        reported_exits.add(eid)
                        outcomes.append({
                            "time": float(t),
                            "kind": "exit",
                            "entities": [eid],
                            "value": None,
                            "src": []
                        })

        # Check collisions and record
        active_list = [eid for eid in active_entities if state.get(eid, {}).get("active", False)]
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                id1, id2 = active_list[i], active_list[j]
                pair = tuple(sorted([id1, id2]))

                s1, s2 = state[id1], state[id2]
                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-6:
                    if pair not in reported_collisions:
                        reported_collisions.add(pair)
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": []
                        })

        t += 1

    return outcomes

