        for _, row in table_rows(motion_node):
            frame = int(row["frame"])
            obj_match = re.match(r'(\d+)\s', row["object"])
            if obj_match:
                obj_id = obj_match.group(1)
                motion_history[obj_id].append({
                    "frame": frame,
                    "x": float(row["x"]),
                    "y": float(row["y"]),
                    "vx": float(row["vx"]),
                    "vy": float(row["vy"]),
                    "speed": float(row["speed"])
                })

        for obj_id in motion_history:
            motion_history[obj_id].sort(key=lambda r: r["frame"])

        for obj_id, history in motion_history.items():
            mat = obj_materials.get(obj_id, "rubber")
            for i in range(1, len(history)):
                h1, h2 = history[i-1], history[i]
                dt = h2["frame"] - h1["frame"]
                if dt <= 0:
                    continue
                dx = h2["x"] - h1["x"]
                dy = h2["y"] - h1["y"]
                avg_vx = (h1["vx"] + h2["vx"]) / 2
                avg_vy = (h1["vy"] + h2["vy"]) / 2

                if abs(avg_vx) > 0.01:
                    k_est = dx / (avg_vx * dt)
                    if 0 < k_est < 0.1:
                        k_estimates.append(k_est)
                if abs(avg_vy) > 0.01:
                    k_est = dy / (avg_vy * dt)
                    if 0 < k_est < 0.1:
                        k_estimates.append(k_est)

                s1, s2 = h1["speed"], h2["speed"]
                if s1 > 0.1:
                    decel = (s1 - s2) / dt
                    if decel > 0:
                        if mat == "rubber":
                            friction_rates_rubber.append(decel)
                        else:
                            friction_rates_metal.append(decel)

        if events_node:
            for line in events_node.get("lines", []):
                em = re.match(r'Frame (\d+): Object (\d+)\s*\(.*?\)\s*exits the scene', line)
                if em:
                    frame = int(em.group(1))
                    obj_id = em.group(2)
                    if obj_id in motion_history:
                        for h in motion_history[obj_id]:
                            if h["frame"] <= frame:
                                exit_bounds_seen.append(max(abs(h["x"]), abs(h["y"])))

    k = sum(k_estimates) / len(k_estimates) if k_estimates else 1.0/35.0
    friction_rubber = sum(friction_rates_rubber) / len(friction_rates_rubber) if friction_rates_rubber else 0.0125
    friction_metal = sum(friction_rates_metal) / len(friction_rates_metal) if friction_rates_metal else 0.006
    exit_bound = sum(exit_bounds_seen) / len(exit_bounds_seen) if exit_bounds_seen else 3.5

    _cached_physics = {
        "K": max(0.01, min(k, 0.05)),
        "friction_rubber": max(0.003, min(friction_rubber, 0.03)),
        "friction_metal": max(0.001, min(friction_metal, 0.015)),
        "exit_bound": max(3.0, min(exit_bound, 4.0)),
        "collision_dist": 0.55
    }
    return _cached_physics

def reset_physics_cache():
    global _cached_physics
    _cached_physics = None

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    reset_physics_cache()

    if horizon is None:
        horizon = recorded_end(doc, scope)
    if horizon is None:
        horizon = 127.0

    ent_mat = get_entity_materials(doc, scope)
    phys = get_physics_params(doc)
    K = phys["K"]
    FRICTION_RUBBER = phys["friction_rubber"]
    FRICTION_METAL = phys["friction_metal"]
    EXIT_BOUND = phys["exit_bound"]
    COLLISION_DIST = phys["collision_dist"]

    station_threshold = params.get("stationary_threshold", 0.1)

    inputs_by_frame = defaultdict(list)
    for inp in inputs:
        frame = int(inp["time"])
        inputs_by_frame[frame].append(inp)

    if not inputs_by_frame:
        return []

    all_frames = sorted(inputs_by_frame.keys())
    sim_start = all_frames[0]

    if start is None:
        start = float(sim_start)

    start_frame = max(sim_start, int(math.ceil(start)))

    state = {}
    active_entities = set()

    def process_inputs_at(frame):
        for inp in inputs_by_frame.get(frame, []):
            for eid in inp["entities"]:
                state[eid] = {
                    "x": inp["fields"]["x"],
                    "y": inp["fields"]["y"],
                    "vx": inp["fields"]["vx"],
                    "vy": inp["fields"]["vy"],
                    "material": ent_mat.get(eid, "rubber"),
                    "active": True
                }
                active_entities.add(eid)

    def apply_physics():
        for eid in list(active_entities):
            s = state.get(eid)
            if not s or not s["active"]:
                continue
            s["x"] += s["vx"] * K
            s["y"] += s["vy"] * K

            speed = math.hypot(s["vx"], s["vy"])
            fric = FRICTION_RUBBER if s["material"] == "rubber" else FRICTION_METAL

            if speed > 0:
                if speed <= fric:
                    s["vx"] = 0.0
                    s["vy"] = 0.0
                else:
                    scale = (speed - fric) / speed
                    s["vx"] *= scale
                    s["vy"] *= scale

    def handle_collisions():
        active_list = [eid for eid in active_entities if state.get(eid, {}).get("active", False)]
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                id1, id2 = active_list[i], active_list[j]
                s1, s2 = state[id1], state[id2]

                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-6:
                    nx, ny = dx / dist, dy / dist

                    m1 = 2.0 if s1["material"] == "metal" else 1.0
                    m2 = 2.0 if s2["material"] == "metal" else 1.0

                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:
                        impulse = 2.0 * dvn / (1.0/m1 + 1.0/m2)
                        s1["vx"] -= impulse/m1 * nx
                        s1["vy"] -= impulse/m1 * ny
                        s2["vx"] += impulse/m2 * nx
                        s2["vy"] += impulse/m2 * ny

                        sep = (COLLISION_DIST - dist) * 0.5 + 0.01
                        s1["x"] += nx * sep
                        s1["y"] += ny * sep
                        s2["x"] -= nx * sep
                        s2["y"] -= ny * sep

    # Replay from sim_start to start_frame
    process_inputs_at(sim_start)

    t = sim_start + 1
    while t < start_frame:
        process_inputs_at(t)
        apply_physics()
        handle_collisions()

        for eid in list(active_entities):
            s = state.get(eid)
            if s and s["active"]:
                if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                    s["active"] = False
                    active_entities.discard(eid)
        t += 1

    # Simulate from start_frame to horizon
    outcomes = []
    reported_collisions = set()
    reported_exits = set()

    t = start_frame
    horizon_frame = int(math.ceil(horizon))

    while t <= horizon_frame:
        process_inputs_at(t)
        apply_physics()
        handle_collisions()

        for eid in list(active_entities):
            s = state.get(eid)
            if s and s["active"]:
                if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                    s["active"] = False
                    if eid not in reported_exits:
                        reported_exits.add(eid)
                        outcomes.append({
                            "time": float(t),
                            "kind": "exit",
                            "entities": [eid],
                            "value": None,
                            "src": []
                        })

        active_list = [eid for eid in active_entities if state.get(eid, {}).get("active", False)]
        for i in range(len(active_list)):
            for j in range(i + 1, len(active_list)):
                id1, id2 = active_list[i], active_list[j]
                pair = tuple(sorted([id1, id2]))

                s1, s2 = state[id1], state[id2]
                dx = s1["x"] - s2["x"]
                dy = s1["y"] - s2["y"]
                dist = math.hypot(dx, dy)

                if dist < COLLISION_DIST and dist > 1e-6:
                    if pair not in reported_collisions:
                        reported_collisions.add(pair)
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": []
                        })

        t += 1

    return outcomes
